    /// Konfiq köhnəlibsə serverdən yeniləyir. 404: mənbə naməlum və ya söndürülüb.
    func refreshConfig(force: Bool = false) {
        guard started else { return }
        let now = env.now()
        let fetchedAt = store.get(Keys.configAt).flatMap { Int64($0) } ?? 0
        if !force, fetchedAt != 0, now - fetchedAt >= 0, now - fetchedAt < config.ttlMs { return }
        let result = transport.get(url: endpoint + "/v1/" + key + "/config", etag: store.get(Keys.configEtag))
        switch result.status {
        case 200:
            guard let body = result.body, let parsed = RemoteConfig.parse(body) else { return }
            config = parsed
            store.put(Keys.config, body)
            if let etag = result.etag { store.put(Keys.configEtag, etag) } else { store.remove(Keys.configEtag) }
            store.put(Keys.configAt, String(now))
        case 304:
            store.put(Keys.configAt, String(now))
        case 404:
            config = RemoteConfig.disabled
            store.put(Keys.config, "{\"enabled\":false,\"ttl_s\":86400}")
            store.remove(Keys.configEtag)
            store.put(Keys.configAt, String(now))
        default:
            return
        }
        if !config.enabled { queue.clear() }
